    explanation: '宅地造成及び特定盛土等規制法（造成宅地防災区域・監督処分）に関する正確な理解を問う設問である。各選択肢の正誤根拠は、選択肢ごとの解説を参照のこと。\n【図解】宅地造成及び特定盛土等規制法（造成宅地防災区域・監督処分）の要点\n→ 造成宅地防災区域：都道府県知事が指定（居住者等への危害のおそれが大きい一団の造成宅地）\n→ 所有者等：災害防止措置の努力義務、知事は必要な措置を勧告可能\n★ 無許可工事・技術基準不適合：知事による工事停止命令・是正措置命令の対象\n→ 監督処分の対象：工事主のほか請負人・現所有者等にも及ぶ場合あり、罰則もあり',
